"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6069],{48840:e=>{e.exports=JSON.parse('{"functions":[{"name":"Confetti","desc":"Starts a confetti burst at `origin` and returns the anchor part holding it.\\n\\nThe part is parented to [Workspace] and cleans itself up: the emit loop destroys\\nit once `length` elapses. Destroy the returned part yourself to cut the effect\\nshort.\\n\\nThis spawns and plays sound on whichever realm calls it, so calling it on the\\nserver shows the effect to everyone, and on the client only to that player.\\n\\n```lua\\nConfetti(rewardChest:GetPivot(), 3)\\n```","params":[{"name":"origin","desc":"Where the burst is centred","lua_type":"CFrame"},{"name":"length","desc":"Seconds to keep emitting (defaults to 2)","lua_type":"number?"}],"returns":[{"desc":"Anchor part holding the emitters and sounds","lua_type":"BasePart"}],"function_type":"static","source":{"line":109,"path":"src/Shared/Class/Confetti.luau"}},{"name":"ui","desc":"Bursts confetti inside a GUI. Pieces are plain Frames parented to a\\nfull-size container under `parent`, thrown in an upward fan from `origin`\\n(absolute screen pixels; defaults to the centre of `parent`, resolved in\\nscale so it holds before layout) and pulled\\ndown by gravity until they fade out. Plays the pop sound.\\n\\nReturns a function that cuts the burst short; the container otherwise\\ndestroys itself after every piece has died.\\n\\n`parent` must not hold a UIListLayout or UIGridLayout: the layout would\\nplace the full-size container as a cell and push its other children.","params":[{"name":"parent","desc":"Where the pieces live (must not clip descendants)","lua_type":"GuiObject"},{"name":"origin","desc":"Absolute screen position of the burst","lua_type":"Vector2?"}],"returns":[{"desc":"Cancels the burst","lua_type":"() -> ()"}],"function_type":"static","source":{"line":194,"path":"src/Shared/Class/Confetti.luau"}},{"name":"portal","desc":"[Confetti.ui] on a ScreenGui of its own, one DisplayOrder above the one\\nholding `source`. Nothing in `source`\'s tree owns the burst, so a clipping\\nancestor (a ScrollingFrame) can\'t cut it and closing the window, switching\\nits tab or unmounting `source` mid-burst leaves the pieces flying. The\\nlayer copies the source ScreenGui\'s inset settings, so `origin` (absolute\\npixels as `source` reports them) lands on the same spot, and it is\\ndestroyed after the burst. A `source` outside any ScreenGui (a UI Labs\\nstory) bursts in place through [Confetti.ui] instead.","params":[{"name":"source","desc":"What the burst belongs to; its centre is the default origin","lua_type":"GuiObject"},{"name":"origin","desc":"Absolute screen position of the burst","lua_type":"Vector2?"}],"returns":[],"function_type":"static","source":{"line":291,"path":"src/Shared/Class/Confetti.luau"}}],"properties":[],"types":[],"name":"Confetti","desc":"Fires a burst of colored confetti with sound at a point in the world, or\\n(via [Confetti.ui]) inside a GUI, or (via [Confetti.portal]) on a GUI\\nlayer of its own that outlives the GUI it came from.\\n\\nSix [ParticleEmitter]s \u2014 one per palette color \u2014 are cloned onto an invisible\\nanchor part, along with a one-shot pop and a looping white-noise bed. The emitters\\nare pulsed in a loop for the requested duration rather than emitting continuously,\\nwhich gives the burst a staggered, hand-thrown feel.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":16,"path":"src/Shared/Class/Confetti.luau"}}')}}]);